if MOCK_MODE=signal "$BASH" "$HOME/installer" signal > "$HOME/control-signal.out" 2> "$HOME/control-signal.err"; then signal_rc=0; else signal_rc=$?; fi
[[ $signal_rc == 143 ]] || { echo 'CONTROL-FAILED mock signal' >&2; exit 98; }
printf 'exit3=%s signal=%s\n' "$control_rc" "$signal_rc" > "$HOME/control-status.txt"
printf 'CALL\0%s\0%s\0failure\0END\0CALL\0%s\0%s\0signal\0END\0' "$BASH" "$HOME/installer" "$BASH" "$HOME/installer" >> "$HOME/control-expected.bin"
/usr/bin/cmp -s "$HOME/calls.bin" "$HOME/control-expected.bin" || { echo 'CONTROL-FAILED mock invocation count' >&2; exit 98; }
/usr/bin/mv "$HOME/calls.bin" "$HOME/control-calls.bin"
/usr/bin/mv "$HOME/env.bin" "$HOME/control-env.bin"
: > "$HOME/calls.bin"; : > "$HOME/env.bin"
